window.kbParts["paper-46afeb3519127be5"] = {"qs":{"江苏 2025 C类 申论#1":{"stem":"“给定资料1-4”列举了近年来农村不同领域出现的一些新职业及其对乡村发展的推动作用，请用一段话对此归纳概\n括。（20分）\n要求：紧扣给定资料，全面、准确，篇幅不超过250字。","options":[],"answer":"","analysis":"近年来，农村涌现出多个新职业助力乡村发展，具体有：在乡村运营领域，农村职业经理人发挥带头作用，盘\n活乡村资源，开展专业化运营，催生新业态，打造新经济，引进项目，吸引投资，带动村级集体经济创收；在乡村\n旅游领域，观鸟旅游“鸟导”依托当地丰富鸟类资源，发展生态旅游，吸引游客，拓宽村民收入渠道，提升经济效益；\n在农业生产领域，植保无人机飞手凭借专业技能，运用智慧农业工具，提升作业效率，获得村民认可，推动农业现\n代化；在民宿服务领域，“民宿管家”通过提升专业素养和服务品质，增强民宿核心吸引力，促进行业发展。\n   参考答案说明：本参考答案按照“农村不同领域出现的新职业及其推动作用”的结构，具体介绍了“农村职业经理\n人”“观鸟旅游‘鸟导’”“植保无人机飞手”“民宿管家”四个新职业其作用，各条答案要点之间在内容上相互并列，没有交\n叉，并以一段话的形式进行呈现。","figs":[],"state":"已标记","notes":[],"domains":["经济","社会治理","科技"],"nature":"综合题","current":false,"links":[{"id":"k-c739cbdf7b1db8d1","label":"农村职业经理人通过专业化运营盘活乡村资源、带动村级集体经济增收","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"催生新业态，打造新经济，引进项目，吸引投资，带动村级集体经济创收","why":"概括乡村运营领域的职业作用时，需说明专业运营如何带来业态、项目和集体收益。","origin":"逐题标记"},{"id":"k-262e4c84d872c539","label":"观鸟导游依托鸟类资源发展生态旅游并拓宽村民增收渠道","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"依托当地丰富鸟类资源，发展生态旅游，吸引游客，拓宽村民收入渠道","why":"概括乡村旅游领域的职业作用时，需交代鸟类资源如何通过旅游服务转化为村民收入。","origin":"逐题标记"},{"id":"k-ef85d813e69bf8bb","label":"植保无人机飞手以专业化作业提高农业生产效率","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"凭借专业技能，运用智慧农业工具，提升作业效率","why":"概括农业生产领域的职业作用时，需把飞手的专业技能与智慧农业工具的应用及效率提升联系起来。","origin":"逐题标记"},{"id":"k-4b97d2768a1c9e2e","label":"民宿管家以专业服务增强乡村民宿吸引力","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"通过提升专业素养和服务品质，增强民宿核心吸引力，促进行业发展","why":"概括民宿服务领域的职业作用时，需说明专业素养和服务品质如何促进民宿业发展。","origin":"逐题标记"},{"id":"s-c898afc5816920c2","label":"按领域归类并逐项概括对象及其作用","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"各条答案要点之间在内容上相互并列","why":"需从多则材料中提取各职业及其作用，按领域配对后并列压缩成一段。","origin":"逐题标记","originalId":"s-79e473de74fcdd89"}]},"江苏 2025 C类 申论#2":{"stem":"请结合“给定资料5”中水秀社区的“‘百姓系列’社区工作法”，谈谈你对“每位居民都是我们服务的对象，也是我们依\n靠的力量”这句话的理解和认识。（20分）\n要求：观点正确，分析透彻，层次分明，篇幅300字左右。","options":[],"answer":"","analysis":"这句话体现了居民在社区治理中兼具服务对象与治理主体的双重身份，水秀社区创新实施“百姓系列”社区工作\n法，推进社区微改造工作，充分体现了这一理念，值得肯定推广。\n  “每位居民都是我们服务的对象”是指：水秀社区以服务群众为导向，满足居民多元化服务需求。对于居民的提\n案，桩桩件件都要回应好；对待社区存在的问题，要现场调研，广听建议，妥善解决。\n  “也是我们依靠的力量”是指：水秀社区引导居民主动参与治理，汲取群众智慧。建立“百姓提案”等常态化工作机\n制，向居民征求改造规划意见，采纳合理建议，并通过社区环境、硬件的变化提升，激发群众共同参与社区治理的\n热情。\n  因此，社区治理既要坚持服务为民，更要依靠居民自治，才能实现治理与服务的良性循环。\n  参考答案说明：（1）思路方面，本参考答案按照词句解释题“总体释义+展开解释+总结”的一般答题思路展开。\n（2）内容方面，本参考答案先解释了画线句子的总体含义并表明了观点，然后分别从行政裁量的“每位居民都是我们\n服务的对象”和“也是我们依靠的力量”两个方面进行展开解释，最后在“总结”部分提出了对策。（3）词句表达方面，\n本参考答案加上了“是指”“因此”等连接词来承接上下文。","figs":[],"state":"已标记","notes":[],"domains":["社会治理"],"nature":"综合题","current":false,"links":[{"id":"k-7c2506a3f1a6ed3d","label":"社区治理中居民兼具服务对象与治理主体的双重身份","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"居民在社区治理中兼具服务对象与治理主体的双重身份","why":"双重身份是理解题干引语的核心判断。","origin":"逐题标记"},{"id":"k-e59e53c80833bd3e","label":"常态化居民提案机制通过回应诉求和吸纳建议促进居民参与","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"M1","quote":"如今“百姓提案”已经成为水秀社区的常态化机制。","why":"提案机制把居民表达需求、社区回应诉求和居民参与治理联系起来。","origin":"逐题标记"},{"id":"k-41d7650e2bf9e3b5","label":"可感知的社区微改造成效提升居民参与治理的积极性","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"M1","quote":"活环境的变化，参与治理的积极性大大提高。","why":"居民感受到环境改善后更愿意参与，说明服务成效如何反过来促进共治。","origin":"逐题标记"},{"id":"s-43e39afd29a17e74","label":"概括引语主旨并结合材料分层阐释各层含义","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"总体释义+展开解释+总结","why":"需先提炼引语主旨，再分别用材料中的做法解释两个分句并归纳其联系。","origin":"逐题标记","originalId":"s-49888ee82037dd2a"}]},"江苏 2025 C类 申论#3":{"stem":"请根据“给定资料6”，以山阳镇社会治理和社会事业办公室的名义，给镇党委写一份请示，提请召开“村级治理经\n验现场交流会”。（20分）\n要求：主题明确，理由充分，措辞妥帖，基本要素齐全，篇幅350字左右。","options":[],"answer":"","analysis":"关于召开村级治理经验现场交流会的请示\n镇党委：\n  近年来，我镇在办好民生实事、做好村级治理工作方面，涌现出了一批各具特色的村级治理典型，其经验做法\n成效显著，受到群众广泛好评，具有示范推广价值。\n   单圩村设立“百姓议事点”，听民意、察民情，解决村民急难愁盼问题，激发村民参与协商议事热情；中关村推\n行“宅基议事会”民主议事制度，主要议题聚焦村民利益相关事务，六年来成功解决五十多项问题。\n  为进一步树立典型，充分发挥典型引领作用，提升全镇村级治理水平，我办计划于12月下旬在单圩村召开村级\n治理经验现场交流会，在镇辖18个村推广单圩村和中关村治理的先进经验。\n  妥否，请批示。\n                                        山阳镇社会治理和社会事业办公室\n                                               XXXX年XX月XX日\n  参考答案说明：（1）格式方面，本参考答案写到了“标题”“主送机关”“正文”“落款”四个部分。（2）正文部分，一\n方面从内容上来看，本参考答案的开头先写到了山阳镇开展村级治理工作的概况；主体部分介绍了单圩村和中关村\n的经验做法及其成效，以及山阳镇社会治理和社会事业办公室的工作计划；结尾部分征询上级部门的意见。另一方\n面，形式上，本参考答案做到了分段、分条撰写，整体上条理较为清晰。","figs":[],"state":"已标记","notes":[],"domains":["社会治理","公共管理"],"nature":"综合题","current":false,"links":[{"id":"k-7d219802f2b7b6a9","label":"村级协商围绕村民切身利益议题组织群众参与","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"主要议题聚焦村民利益相关事务，六年来成功解决五十多项问题。","why":"中关村的议题选择和问题解决成效具体说明了协商经验的推广价值。","origin":"逐题标记"},{"id":"k-e955a9efc46a5909","label":"公开议事办理过程和结果并跟踪回访有助于落实村民诉求","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"M1","quote":"办理过程、最终结果全程向村民公开。通过走访询问、电话回访等方式及时跟踪落实","why":"该做法说明单圩村如何把村民提出的问题落实到办理和反馈环节。","origin":"逐题标记"},{"id":"k-e568b5d3a53d68e7","label":"实际治理成效和群众认可可作为推广村级治理典型的依据","catalog_id":null,"type":"观点与论证","role":"解题依据","field":"answer","quote":"成效显著，受到群众广泛好评，具有示范推广价值。","why":"两项判断为召开现场交流会、在全镇推广两村做法提供理由。","origin":"逐题标记"},{"id":"s-9f175b7eb1a79028","label":"提炼案例做法及成效以论证拟办事项","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"主体部分介绍了单圩村和中关村","why":"需要从两村案例中筛选代表性做法及其成效，支撑现场推广的理由。","origin":"逐题标记","originalId":"s-2036a5081dcba510","additionalEvidence":[{"id":"s-232ced822a26c846","label":"按行文对象组织报批缘由、事项安排和批示请求","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"“标题”“主送机关”“正文”“落款”四个部分","why":"需要写明呈报对象和发文主体，在正文中交代拟办安排并向上级请求批示。","origin":"逐题标记"}]}]},"江苏 2025 C类 申论#4":{"stem":"假如你是“给定资料7”中戴窑镇政府机关的一名工作人员，请围绕戴窑镇稻米产业特色，给兴化市政府网站“今日\n兴化”栏目写一篇宣传稿。（40分）\n要求：\n（1）结合给定资料，自选角度，自拟标题；\n（2）内容充实，结构完整；\n（3）篇幅1000字左右。","options":[],"answer":"","analysis":"“稻”梦戴窑，“香”约兴化\n    戴窑镇地处江淮腹部，河网交织、土地肥沃，坐拥“鱼米之乡”天然禀赋，是兴化大米主产区。戴窑镇牢记“粮食\n也要打出品牌”重要指示，紧扣“水韵苏米”建设，依托优越水土条件，培育出稻谷金黄、晶莹透亮、米粒饱满、柔软\n油润、口感特佳的国家地理标志产品。近年更构建起全产业链发展模式，让水乡米香飘向四方。\n    科技赋能，智慧田野生出“金稻穗”。兴化市与国内知名农业大学共建，建立智慧稻作模式，推广先进的水稻机\n插缓混一次施肥技术和绿色防控技术。建成江苏省水稻项目核心试验区，实现每公顷1.22万公斤的全国最高单产，\n品种更优、品质更高。2023年，兴化市入选首批“全国农业科技现代化先行县”，戴窑镇功不可没，年粮食总产量已逾\n25亿斤，粮食加工企业实现工业总产值141.83亿元。\n    贤人辈出，新农人激活“田间新活力”。曾经，戴窑镇交通不便，种地辛苦，年轻人纷纷外出。如今，村里道路\n设施日益完善，一批像小马哥这样的新农人选择返乡创业。他们包下大片农田，积极学习数字化种植技术，用新理\n念、新技术武装头脑，成为戴窑镇粮食生产的主力军。\n\n  标准领航，全链打造“产业新高地”。戴窑镇成立技术行业协会，制定行业标准和质量安全标准，引导企业向精\n深加工升级。目前，镇内有大米加工企业52家，年加工能力700万吨，产品畅销多个地区。国家级、省级、市级龙头\n企业齐聚，“贤人”“板桥”等众多著名品牌熠熠生辉，形成了集原粮生产、稻米加工、贸易于一体的粮食市场和产业集\n中区“米企一条街”。\n  平台增效，数字物流畅通“全国大市场”。随着销售半径扩大，戴窑镇米企以数字物流破局运输难题。农业产业\n化国家级重点龙头企业万家福米业便是典型代表：企业配备两条日加工600吨的自动化精米加工流水线，拥有11.035\n万吨标准粮食低温仓容。每年销售旺季，通过网络平台高效调配运力，降本增效。其明星产品“老娘舅”稻香米年销量\n超6万吨，“光明”“粒粒源”等品牌大米畅销全国。\n  文化铸魂，稻作文明孕育“振兴同心圆”。兴化推动产业与文化融合，建立稻米文化展览馆，展示稻米种植加工\n历史文化。2024年9月22日，“兴化大米”入选国际稻米品牌百强榜。独具风格的稻米文化带动经济发展，提升乡村审\n美，增强居民认同感和归属感，促进社会和谐，推动治理水平不断提升。\n  从田间到餐桌，从传统到现代，戴窑镇正以稻米产业为核心，在多方协同推动下，不断书写乡村振兴的新篇\n章，让兴化大米的品牌更加响亮，让这片鱼米之乡焕发出新的生机与活力。\n文章分析\n                      “稻”梦戴窑，“香”约兴化\n  【标题的优点：一方面，在内容上，标题突出了主题；另一方面，在形式上，采用对城市结构，颇有亮点。】\n  （1）戴窑镇地处江淮腹部，河网交织、土地肥沃，坐拥“鱼米之乡”天然禀赋，是兴化大米主产区。（2）戴窑镇\n牢记“粮食也要打出品牌”重要指示，紧扣“水韵苏米”建设，依托优越水土条件，培育出稻谷金黄、晶莹透亮、米粒饱\n满、柔软油润、口感特佳的国家地理标志产品。近年更构建起全产业链发展模式，让水乡米香飘向四方。\n  【开头的优点：★内容方面。宣传稿的开头首先介绍了戴窑镇优越的水土条件，是兴化大米的主产区；其次，\n介绍了戴窑镇稻米产业发展的总体情况。★文字表达方面。衔接流畅，富有文采。】\n  科技赋能，智慧田野生出“金稻穗”。（1）兴化市与国内知名农业大学共建，建立智慧稻作模式，推广先进的水\n稻机插缓混一次施肥技术和绿色防控技术。（2）建成江苏省水稻项目核心试验区，实现每公顷1.22万公斤的全国最\n高单产，品种更优、品质更高。（3）2023年，兴化市入选首批“全国农业科技现代化先行县”，戴窑镇功不可没，年\n粮食总产量已逾25亿斤，粮食加工企业实现工业总产值141.83亿元。\n  【主体部分1的优点：★核心句：宣传稿的核心句是紧扣“戴窑镇稻米产业特色”这一主题提出的。形式上，它在\n段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“科技赋能”这一\n方面展开论述的。★具体展开：（1）指出兴化市与农业大学共建，建立智慧稻作模式；（2）介绍了通过建成江苏\n省水稻项目核心试验区，实现增产提质；（3）强调了兴化市通过现代科技推动农业发展的成果。注意：以上三个方\n面的内容都是紧扣“科技赋能，智慧田野生出‘金稻穗’”这个核心句进行分析论述的，具体展开的内容针对性强，层次\n丰富。在具体内容的展开上主要采用了讲道理、列数字的论证方式，论述清晰透彻。】\n  贤人辈出，新农人激活“田间新活力”。（1）曾经，戴窑镇交通不便，种地辛苦，年轻人纷纷外出。（2）如\n今，村里道路设施日益完善，一批像小马哥这样的新农人选择返乡创业。（3）他们包下大片农田，积极学习数字化\n种植技术，用新理念、新技术武装头脑，成为戴窑镇粮食生产的主力军。\n  【主体部分2的优点：★核心句：宣传稿的核心句是紧扣“戴窑镇稻米产业特色”这一主题提出的。形式上，它在\n段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“新农人激活‘田\n间新活力’”这一方面展开论述的。★具体展开：（1）先指出过去戴窑镇交通不便，年轻人不愿种地；（2）接着介绍\n现在道路设施完善，新农人返乡创业；（3）新农人通过学习新技术、新理念，成为粮食生产主力军。注意：以上三\n个方面的内容都是紧扣“贤人辈出，新农人激活‘田间新活力’”这个核心句进行分析论述的，具体展开的内容针对性\n强，层次丰富。在具体内容的展开上主要采用了讲道理的方式，论述清晰有力。】\n  标准领航，全链打造“产业新高地”。（1）戴窑镇成立技术行业协会，制定行业标准和质量安全标准，引导企业\n向精深加工升级。（2）目前，镇内有大米加工企业52家，年加工能力700万吨，产品畅销多个地区。国家级、省\n级、市级龙头企业齐聚，“贤人”“板桥”等众多著名品牌熠熠生辉，形成了集原粮生产、稻米加工、贸易于一体的粮食\n市场和产业集中区“米企一条街”。\n  【主体部分3的优点：★核心句：宣传稿的核心句是紧扣“戴窑镇稻米产业特色”这一主题提出的。形式上，它在\n段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“标准领航，引\n导产业升级”这一方面展开论述的。★具体展开：（1）先介绍了戴窑镇成立技术行业协会，制定标准，引导企业升\n级；（2）接着指出戴窑镇汇聚众多大米加工企业，形成粮食市场和产业集中区“米企一条街”。注意：以上两个方面\n的内容都是紧扣“标准领航，全链打造‘产业新高地’”这个核心句进行分析论述的，具体展开的内容针对性强，层次丰\n富。在具体内容的展开上主要采用了讲道理、列数字的论证方式，论述清晰深刻。】\n  平台增效，数字物流畅通“全国大市场”。（1）随着销售半径扩大，戴窑镇米企以数字物流破局运输难题。\n（2）农业产业化国家级重点龙头企业万家福米业便是典型代表：企业配备两条日加工600吨的自动化精米加工流水\n\n线，拥有11.035万吨标准粮食低温仓容。每年销售旺季，通过网络平台高效调配运力，降本增效。其明星产品“老娘\n舅”稻香米年销量超6万吨，“光明”“粒粒源”等品牌大米畅销全国。\n  【主体部分4的优点：★核心句：宣传稿的核心句是紧扣“戴窑镇稻米产业特色”这一主题提出的。形式上，它在\n段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“数字物流助力\n市场畅通”这一方面展开论述的。★具体展开：（1）先介绍了戴窑镇米企通过数字物流破解运输难题；（2）接着介\n绍了万家福米业通过网络平台调配运力，降本增效的典型案例。注意：以上两个方面的内容都是紧扣“平台增效，数\n字物流畅通‘全国大市场’”这个核心句进行分析论述的，具体展开的内容针对性强，层次丰富。在具体内容的展开上主\n要采用了讲道理和举例子的方式，论述充实深刻。】\n  文化铸魂，稻作文明孕育“振兴同心圆”。（1）兴化推动产业与文化融合，建立稻米文化展览馆，展示稻米种植\n加工历史文化。（2）2024年9月22日，“兴化大米”入选国际稻米品牌百强榜。（3）独具风格的稻米文化带动经济发\n展，提升乡村审美，增强居民认同感和归属感，促进社会和谐，推动治理水平不断提升。\n  【主体部分5的优点：★核心句：宣传稿的核心句是紧扣“戴窑镇稻米产业特色”这一主题提出的。形式上，它在\n段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“稻米产业与文\n化结合”这一方面展开论述的。★具体展开：（1）先介绍了兴化市推动产业与文化融合，建立稻米文化展览馆；\n（2）接着指出“兴化大米”入选国际稻米品牌百强榜；（3）最后，阐述了稻米文化的重要作用。注意：以上三个方面\n的内容都是紧扣“文化铸魂，稻作文明孕育‘振兴同心圆’”这个核心句进行分析论述的，具体展开的内容针对性强，层\n次丰富。在具体内容的展开上主要采用了讲道理的方式，论述清晰透彻。】\n  从田间到餐桌，从传统到现代，戴窑镇正以稻米产业为核心，在多方协同推动下，不断书写乡村振兴的新篇\n章，让兴化大米的品牌更加响亮，让这片鱼米之乡焕发出新的生机与活力。\n  【结尾的优点：宣传稿的结尾回扣了“戴窑镇稻米产业特色”这一主题，并进行了总结展望。】","figs":[],"state":"已标记","notes":[],"domains":["经济","科技","文化"],"nature":"综合题","current":false,"links":[{"id":"k-d08306ba8e76fafd","label":"地方水土禀赋和稻米品质支撑地理标志品牌建设","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"依托优越水土条件，培育出","why":"参考稿以戴窑的水土优势和兴化大米的品质说明地方品牌的形成基础。","origin":"逐题标记"},{"id":"k-118c544df1d44437","label":"校地共建和智慧稻作技术推广促进稻米增产提质","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"建立适宜兴化的智慧稻作模式","why":"材料以校地共建、栽培技术推广和试验区成效说明科技如何改善稻米产量与品质。","origin":"逐题标记"},{"id":"k-5facd10c57465db7","label":"农村交通改善和土地流转为新农人规模种植创造条件","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"借着村里土地流转的机会，他包下了600亩农田，开始新农人之路","why":"小马哥的经历串联了道路桥梁改善、土地流转和规模经营，说明新农人进入稻米生产的条件。","origin":"逐题标记"},{"id":"k-2d8bbc68e8ab0503","label":"行业协会以标准引导稻米精深加工，产业集聚衔接生产、加工和贸易","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"制定大米行业标准和质量安全标准","why":"材料将协会制定标准、企业加工升级和“米企一条街”的产加销集聚作为全产业链发展的具体表现。","origin":"逐题标记"},{"id":"k-cdb2446778680ce0","label":"网络货运平台按需补充运力，降低稻米旺季运输成本","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"由于旺季时的短期运输需求激增，使用平台是一件省时又省钱","why":"万家福米业的案例说明，销售范围扩大后，平台可以补充常用车辆的运力，应对旺季短期运输需求。","origin":"逐题标记"},{"id":"k-9b00ee5a077b63a2","label":"稻米文化展示扩大产业影响并增强乡村居民认同","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"展示稻米种植加工的历史和文化，提升粮食市场影响力","why":"材料以稻米文化展览馆说明产业发展与文化传承相结合的做法，并指出其对市场影响力和居民归属感的作用。","origin":"逐题标记"},{"id":"s-cabc6af5d656b214","label":"围绕指定对象筛选并归类产业特色","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"请围绕戴窑镇稻米产业特色","why":"题目限定了宣传对象，写作需从兴化市层面和戴窑镇层面的叙述中选取相关信息，并按产业特色归类。","origin":"逐题标记","originalId":"s-e4c3dfa0f0d05dfb","additionalEvidence":[{"id":"s-6d8337b1f5e0e9bc","label":"用段首主旨句统领做法、案例和成效","catalog_id":null,"type":null,"role":"解题依据","field":"answer","quote":"在具体内容的展开上主要采用了讲道理和举例子的方式","why":"参考稿先概括数字物流的作用，再用万家福米业调配旺季运力的做法和成效支撑段落主旨。","origin":"逐题标记"}]}]}},"mats":{"00fc517bdfac833b":["材料1","材料1\n  英雄辈出今如何，请看“乡村CEO”。近年来，在H市Y区活跃着一批农村职业经理人，他们被乡亲们亲切称为“乡\n村CEO”。他们有理想、有学历、有技能，应Y区“英雄帖”的召唤而来，为乡村建设发展进行专业化运营。在乡亲们看\n来，他们就是一群帮助乡村做生意的带头人。截至目前，该区共有27名农村职业经理人活跃在一线。在他们及其运\n营团队的努力下，永安村、青山村、新港村等一批乡村纷纷“出圈”，乡村发展被注入了新动能。\n  在“乡村CEO”小王总看来，“Y区有着丰富的农村文旅资源，多项现代化农业建设成果和多个政府项目在此落地，\n这些优势对于我们开展乡村运营起到了关键作用。”小王总和他的团队负责北洋镇“长潭湖畔旅发”项目的运营，他们\n是全镇的“乡村CEO”，全镇的老百姓都是股东。\n  在乡亲们眼里，“他们不是村干部，但起着村干部的作用”。这些“乡村CEO”干起活来风风火火，效率特别高。永\n安村的小周总结合村情实际，带动村民做好老字号的新文章，在传统土特产梨膏糖的基础上，开发出新品种梨膏棒\n棒糖系列产品，作为伴手礼亮相巴黎奥运会；青山村的小韩总有从事旅游业的经验，更有浓厚的乡村情怀，她聘请\n专业团队规划村里的旅游设施，投资建设了童玩区、戏水区、休闲露营区、骑行驿站等，还与高校合作，吸引了一\n批大学生志愿者参加到自己的团队中来。\n  “随着‘乡村运营’的理念日渐成熟，谁来经营、如何经营成为乡村发展的关键所在。发展乡村经济、增强农村造血\n功能，需要专业人才的加入，以此催生新业态，打造新经济。探索推行农村职业经理人来运营发展乡村意义重\n大。”Y区农业农村局杨局长表示。据统计，近年来Y区累计引进各类项目122个，吸引有效投资2.99亿元，为村级集\n体经济创收超1亿元。今后，该区还将加大本土农村职业经理人培养力度，让更多“乡村CEO”在Y区不断涌现，助力\n乡村振兴。",["7e3ca2d8bd92160cb8df.pdf",1]],"3af9e24c72ed2aa5":["材料2","材料2\n  “观鸟，请到婺源来。”早上6点，当第一缕阳光刚刚洒向婺源的山林溪流时，一批从外地专程赶来的观鸟爱好者\n已经带着“长枪短炮”，在婺源江湾镇晓起村“鸟导”老余的带领下，摆好了架势，随时准备按下镜头。“早晨和傍晚的光\n线不刺眼，鸟儿最喜欢出来，这是拍摄鸟类的最好时段。”“这个拍鸟点很好，距离白腿小隼只有20米左右，今天天气\n又好，希望你们大有收获。”老余边介绍边领着客人上到了自家楼顶的观鸟平台。\n  近年来，婺源已发现鸟类356种，其中国家重点保护野生鸟类84种，这里不仅有“会飞的大熊猫”白腿小隼，有全\n球数量不多的蓝冠噪鹛，还有罗纹鸭、鸳鸯、骨顶鸡等多种珍禽。为此，婺源县重点打造“生态观鸟+”，确立“以鸟为\n媒、对话世界；以鸟为景、感受山水；以鸟为友、牵手婺源”的发展思路，持续擦亮婺源国际生态观鸟目的地品牌，\n婺源成了广大“摄友”和“鸟友”向往的观鸟最佳地，一批过去的农民成了观鸟旅游的“鸟导”。\n   老余原本是一位茶农，从来没想过“以鸟为生”。十几年前，一位专业鸟类摄影家路过时，发现他家旁边的大樟树\n上停着几只白腿小隼，白腿小隼因脸部像熊猫，加上非常珍稀，被鸟友们称为“鸟中大熊猫”，是海内外鸟类摄影师镜\n头中的明星鸟。知道这一情况后，老余热情地邀请摄影家到自家楼顶拍摄。后来摄影家把照片分享到网上，在观鸟\n圈一炮而红，从此老余家的楼顶就成了观鸟圈中的“圣地”，高峰时一年有近万名海内外的摄影师和观鸟爱好者登上这\n个农家小楼。“多的时候一天有几百人，楼顶上人都站不下，见此情景，附近几家也搞起了观鸟平台。”老余自豪地\n说。\n   楼顶观鸟平台火了后，老余还在楼下开了个小饭店，店里贴着珍稀鸟类的图片，配有介绍拍摄鸟类照片注意事\n项的文字说明。饭店生意也跟着火了，全家人都吃上了生态旅游饭：妻子当上了“大厨”，儿媳妇成了服务员，他和两\n个儿子当观鸟导游，儿子还兼任驾驶员，负责到火车站或机场接站，全家人一年到头忙得不亦乐乎，节假日客人多\n时更是应接不暇。“带一个观鸟团每天有五六百元，加上餐饮住宿，一年下来真不少呢。”老余开心地说。在婺源，有\n很多老余这样的村民转变身份，干起了“鸟导”这一新职业，吃上了“观鸟饭”。婺源去年接待游客逾70万人次，创观鸟\n经济效益逾1亿元。",["7e3ca2d8bd92160cb8df.pdf",1]],"7a7ec4d9aa21983c":["材料3","材料3\n  立夏时节，万物繁茂。6月中旬的一天，在C市J区南瑶村，35岁的植保无人机飞手小丁正在操作一台载荷50公\n斤的大型农用无人机，为250亩稻田施肥。“无人机每趟飞出去，在农田里转一圈只要1分钟左右，7000公斤化肥前后\n只花5个小时就喷完了。”“我们每位‘飞手’都配有一辆加装了顶棚的小货车，防止车上装的无人机和发电机、电池淋雨\n受损。我的工作就是把车开到田边，然后操作无人机打农药、施化肥，作业效率是人工的15-50倍。”小丁说。\n  近年来，随着智慧农业的发展，植保无人机作为农业生产中的“新式武器”闪亮登场，也孕育出一个全新的职业\n——植保无人机飞手。在C市，像小丁这样持证上岗的植保无人机飞手目前有40多个。\n\n  小丁是土生土长的农村人，2015年退伍回乡，学会了收割机、插秧机等农业机械的操作和维修。2017年农业植\n保无人机应用后，小丁凭着心灵手巧，花两个月时间考到了无人机飞手证，3个月后便持证上岗了。\n  操作植保无人机，看着就像玩游戏一样，伴随着一阵阵旋翼转动声，一架架植保无人机在飞手的操作下腾空而\n起，沿着农田飞行，机身下的喷头喷出化肥，均匀洒向农田。小丁说，很多人认为飞植保无人机很简单，那是外行\n看热闹，真正操作起来比日常拍摄用的无人机要复杂得多、讲究得多：飞行速度慢，农药在飞行中飘移就会少、穿\n透性好；飞得较低，蒸发变弱，飘移也会少、喷幅小；打药每飞30亩换一次电池，施肥料每200公斤换一次电池……\n这些都是他7年来总结的植保飞手“门道”。另外，C市的田地较为分散，而且田边会有树木或电线杆，自动飞行时无\n人机为了避让，会漏掉一些农田，这就需要飞手手动操作进行补洒，非常考验个人能力。\n  据小丁介绍，“植保无人机主要有载荷50公斤和15公斤两种，大田块、需要大量打药施肥的使用大无人机，如果\n是小田块、洒颗粒封闭药，就要用小无人机了。”小丁回忆，“其实开始时农户是不接受植保无人机的，觉得无人机洒\n下的农药剂量小，怕没有效果。”几年下来，小丁他们专业的操作技能赢得了农户的信任，现在很多种植大户都自购\n了植保无人机，聘请飞手干活。\n  小丁很喜欢现在的职业，很高兴自己走在时代的前列，为把自己的经验分享给对植保无人机感兴趣的人们，他\n还加入对新飞手进行培训的行列中。",["7e3ca2d8bd92160cb8df.pdf",1]],"7bef9dbd97cb48ad":["材料4","材料4\n  一个主题、一个故事、一桌佳肴、一组活动、一种文化共鸣……在莫干山上，4000多名“民宿管家”用他们的创\n意，不断提升着民宿的核心吸引力。\n  “父母刚开始不理解，觉得乡村的民宿管家就是服务员。”95后小孟来自河南，大学毕业后，她来到离家1000公\n里的莫干山，成了一名管理民宿的“山中青年”。当时，“民宿管家”不在我国的职业名录内，全国普通高校、职业院校\n几乎没有设置相关专业课程，民宿业主难以招到合适的管理人才，不少年轻人也因为这项工作缺乏社会认可，不敢\n轻易入行。\n  2021年，D县积极整合公共部门、行业协会和专家团队力量，成立“民宿管家”新职业申报工作小组。2022年6\n月，国家人社部向社会公示了18个新职业信息，“民宿管家”位列其中，成为全国首个以县级政府名义申报的新职业。\n2022年7月，“民宿管家”国家职业技能标准开发工作在D县启动，由D县人民政府和其所属市人社局全力开发编制。经\n过初审、终审，2024年2月，“民宿管家”国家职业标准正式颁布施行，从接待服务、体验服务、市场营销等方面对“民\n宿管家”提出具体要求，并划分出五个职业技能等级。\n  干好新职业既要有“硬实力”，也要有“软技能”。“石头上刻的字有什么渊源？”“莫干山还有哪些名胜古迹？”游客在\n民宿闲聊时说起的话题，小孟都会一一记下来，一个问题一个问题地学习，不断扩充知识储备。现在，提起周边特\n色、地域文化等话题时，她基本可以对答如流，服务起来更有底气。今年3月，包括小孟在内的D县40名“民宿管\n家”通过民宿管家初级工技能等级认定考试，顺利拿到职业技能等级证书，成为首批持证上岗的民宿管家。小孟希望\n有一天能够拿到最高等级证书：“把自己热爱的事情做到最好。”",["7e3ca2d8bd92160cb8df.pdf",2]],"5a3e1b1ae8e821b3":["材料5","材料5\n  微改造，新面貌。原先乱糟糟的小花园改造成了党员花圃、友邻花坛，几十盆各式花草都是居民从家中搬来\n的；粉刷一新的楼道里，带有装饰图案的挂钩，让居民大包小包回家时可以腾出手来开家门；角落里生机盎然的绿\n植代替了过去堆放的杂物；道路边刚刷的座椅上贴着“油漆未干，请勿靠近”的温馨提示……W市水秀社区的这些“微\n观景观”，其改造建议、改造创意都来自居民，既暖心又实用，无声诉说着“百姓提案师”“百姓规划师”们的努力。\n  水秀社区是一个30多年的老社区，区域面积近20万平方米，有1.3万多居民，具有新老居民混杂、人员流动频\n繁、生活方式多样等特征，在环境、空间等诸多方面与居民多元化服务需求难以匹配。\n  “早在2017年，就有居民要求对社区进行环境改造，当时社区党委推出了‘百姓提案大赛’活动，第一件‘提案’是居\n民老张随手写在一份报纸的空白处的建议——在居民区放置‘安全文明上网’的宣传牌，我们至今还珍藏着。”水秀社区\n党委徐书记说。从被动接受管理，到主动参与治理，这份提案可以说见证了水秀居民参与治理从蹒跚学步到规范成\n熟的过程。如今“百姓提案”已经成为水秀社区的常态化机制。走进水秀社区党群服务中心的“友邻客厅”，你会立即被\n密密麻麻写满字的黑板所吸引，停下脚步细细打量，足有二十多条，建议还全都不重样。徐书记指着其中几条打上\n记号的内容说：“社区治理没有小事，你看，停车位紧张、房屋渗水、环卫设施改造，哪怕再琐碎的，只要是居民的\n提案，我们桩桩都要回应好。”\n  在社区辖区内的稻香路上，老牛咸豆浆、凌阿姨粢饭团、飞白咖啡馆等“网红店”经常大排长队，带来十足的烟火\n气。“人多了，车流量就特别大，买菜的市民、吃饭的食客图便利，就把车违停在路边，不但影响环境，店里的生意\n也大受影响。”稻香路上的老商户刘老板说。为了解决这个问题，社区干部都不知跑了多少趟，到现场调研，广泛听\n取居民建议。恰逢市里“水秀·记——老新村活化项目”启动，水秀社区创新实施“百姓规划师”项目，想方设法激发商户\n与居民共同参与社区治理的热情。项目开展后，社区联合有关商户设立了四个便民箱，征求到100多条规划改造意\n见，其中不少合理建议被采纳。“改造后社区有直达稻香市场的小巴士，路边居然还能腾出几十个车位，现在我们商\n户交通顺畅，心情畅快。”刘老板说。\n\n  “从最初的一条建议到如今的一呼百应，我们通过‘百姓提案师’‘百姓规划师’‘百姓营造师’等百姓系列社区工作法，\n从楼道微治理、公共空间微改造、院落微美化到社区微更新，居民切切实实地看到了硬件设施的提升，感受到了生\n活环境的变化，参与治理的积极性大大提高。”一位社区干部感慨地说，“在社区，每位居民都是我们服务的对象，也\n是我们依靠的力量。”",["7e3ca2d8bd92160cb8df.pdf",2]],"29ddaa2dcad763f7":["材料6","材料6\n  近年来，N县山阳镇在办好民生实事、做好村级治理工作方面，涌现出了一批各具特色的村级治理典型。前不\n久，N县电视台的记者来到山阳镇进行实地采访。让我们跟随记者的镜头，走进两个先进村去看一看。\n                      镜头一 单圩村党群服务中心\n  单圩村党群服务中心旁边的巷子里热闹非凡，村干部和村民们围坐在一起，你一言，我一句，为建设乡村献计\n献策。“我们村现在这么漂亮，接下来要怎么保持好，我觉得村里要多考虑。”“现在村里年轻人越来越多，能不能再\n修建一个篮球场，增加一些娱乐活动场所。”……\n  “这里原本只是一个普通的亭子，村民们有事无事都喜欢到这里坐坐，聊聊‘柴米油盐’，说一说‘家长里短’，久而\n久之这里就变成了我们村的‘百姓议事点’。”村党总支委员老胡笑着对记者说，“对我们村干部来说，这里是个听民\n意、察民情的好地方，不仅可以了解村民关注的热点、难点、堵点问题，探索乡村治理新经验，征集基层治理‘金点\n子’，还可以让群众参与到基层治理中来，大家的事大家商量着办，我们村变得越来越和谐了。”\n  为了激发村民参与协商议事的热情，确保他们的声音可以被听到。单圩村还将“百姓议事点”议事事程、解决方\n案、办理过程、最终结果全程向村民公开。通过走访询问、电话回访等方式及时跟踪落实，确保每件事情都能得到\n回应，每个问题都能妥善解决。村民的“问题清单”一个个地被转化为“满意清单”“幸福清单”。“百姓议事点”成为“群众\n办事点”，村民们赞不绝口，“村里对老百姓真的用心用情用力，我们心里都暖洋洋的。”\n  单圩村党支部书记老陈说：“我们村秉承‘有事好商量，众人的事情由众人说了算’的理念，想方设法解决村民的急\n难愁盼问题。今后，我们村将继续发挥‘百姓议事点’作用，让更多村民参与到村庄治理中来。”\n                       镜头二 中关村某村民民宅\n  在中关村的杨大伯家里，村民们围坐在一起，村支书老马正在主持“宅基议事会”。老马指着杨大伯家正在充电的\n电动自行车说：“乡亲们，今天主要是想和大家说说怎么解决电动自行车充电的事情。你们看看，我们村不少人像老\n杨家一样，将电动自行车放在家里充电，这样很容易引起严重火灾事故。”老马说，“一些村民向村委会反映过这个情\n况，提出过建议，我们经过前期调查和协商，打算在每个村民居住点建公共充电桩，充电桩建设完成后，将大大降\n低电动自行车充电的安全风险，并且价格也不贵，大家看看，对这个问题有什么想法和意见？”在场的村民纷纷表示\n同意，还对充电桩的选址、充电服务商选择等问题提出了建议。\n  “宅基议事会”是中关村从2018年开始推行探索的一项民主议事制度，主要议题聚焦于河道治理、村级道路拓宽、\n美丽宅基地建设、消防安全等跟村民利益相关的事务，六年来成功解决了五十多项问题，得到了村民们的广泛支\n持。\n  为进一步树立典型，山阳镇社会治理和社会事业办公室计划于今年12月下旬在单圩村召开村级治理经验现场交\n流会，在镇辖18个村推广单圩村和中关村治理的先进经验。",["7e3ca2d8bd92160cb8df.pdf",3]],"d893167395ce01a8":["材料7","材料7\n   近年来，江苏始终牢记习近平总书记“粮食也要打出品牌”的重要指示，聚力用情推动“水韵江苏”建设。“兴化大\n米”作为“水韵苏米”建设的一个重要品牌，以其稻谷金黄、晶莹透亮、米粒饱满、柔软油润、口感特佳成为国家地理\n标志产品。\n  “积雨如膏土脉滋，春来民事颇相宜。”“宿麦渐看青遍野，新秧初见绿盈池。”兴化地处江淮之间，境内河湖港汊\n纵横交错，与水相伴而生的环境让这里有着得天独厚的地理优势，是名副其实的“鱼米之乡”。兴化名人郑板桥“些小\n吾曹州县吏，一枝一叶总关情”的为民理念与乡土情怀在当地流传甚广，培养了一代又一代的兴化人。多年来，在这\n片沃土上，兴化探索出了一条优质大米种植、加工、销售全产业链的发展之路。\n  为了从“会种田”到“慧种田”，兴化市与国内知名农业大学进行共建，建立适宜兴化的智慧稻作模式，推广最先进\n的水稻机插缓混一次施肥技术和绿色防控技术，在兴化钓鱼村建立了国家粮食丰产工程——江苏省水稻项目核心试\n验区。该试验区以每公顷1.22万公斤的产量，居全国各试验区之首，品种更优、品质也更高。农业科学技术的进步\n和运用，让兴化粮食生产由“望天收”变成了“丰产方”，为兴化大米插上了腾飞的翅膀。2023年，兴化市入选首批“全国\n农业科技现代化先行县”，年粮食总产量已逾25亿斤，粮食加工企业实现工业总产值141.83亿元。\n  戴窑，人杰地灵、贤人辈出，如今戴窑镇是兴化大米的主产区，“贤人”也已成为著名的大米品牌。从前，戴窑流\n传着一句话：“车子摇一摇，到了戴家窑，晴天一身灰，雨天一身泥。”对这句话，土生土长的戴窑人小马哥深有感\n触。小马哥从小就帮助父亲一起干农活，但退伍后的他并没有像父亲一样选择种地，而是在当地做起了泥瓦匠。“一\n年以前我们这里还没有修路和桥，每次播种时需要把农机、农资等物品用船运到田里，收成时再用船把粮食从田里\n运出来，很不方便，太苦太累了。”2018年，小马哥所在的村通上了水泥路，也建起了大桥，让他对种地重拾了信\n心，借着村里土地流转的机会，他包下了600亩农田，开始新农人之路。小马哥在种地之余，还特别喜欢鼓捣鼓\n\n捣“黑科技”，研究研究数字化种植技术。“时代在发展，我们种地的人也要跟上时代的步伐。”他说。现在，兴化已有\n一大批种植大米的新农人，成为兴化市粮食生产的主力军。\n  随着大米产量和质量实效不断扩大，他们成立了技术行业协会，制定大米行业标准和质量安全标准，引导食品\n加工企业向精深加工升级。目前，戴窑镇有大米加工企业52家，年加工能力700万吨，产品畅销江、浙、沪、广东、\n福建等10个地区，占全国大米市场的5%左右。该行业协会还制定了大中小企业发展规划，推动大中小企业共同高质\n量发展。2019年戴窑镇成功入选全国农业产业强镇建设名单，2021年又成功入选江苏省“味稻小镇”推介名单。2024\n年祥兴米业有限公司、万家福米业有限公司入选江苏省智能制造车间名单。目前，戴窑镇有国家级龙头企业2家、省\n级6家、市级17家，有“贤人”“板桥”“祥兴”等多个江苏省级著名品牌，已形成了集原粮生产、稻米加工、贸易于一体的\n粮食市场和粮食加工产业集中区“米企一条街”。\n  戴窑的万家福米业成立于2010年，历经十多年的发展，已成长为当地规模最大的米企之一、农业产业化国家级\n重点龙头企业，拥有日加工600吨自动化精米加工流水线两条，标准粮食低温仓容达11.035万吨，获得ISO9001质量\n管理体系、ISO22000食品安全管理体系等认证，主导产品“老娘舅”“光明”“粒粒源”等类型大米销往全国各地。“每年的\n11月到第二年的1月，是大米加工产业的旺季，原粮运进来，成品米运出去，每天需要大量的运力，除了跟我们厂合\n作的车辆，我们还通过网络平台找车。”万家福米业办公室韦主任说，“最初万家福的销售只是集中在长三角地区，\n2018年之后，企业销售半径扩大，开始往全国辐射，由于旺季时的短期运输需求激增，使用平台是一件省时又省钱\n的方法。”据韦主任介绍，去年“老娘舅”稻香米年销售量超过6万吨，成为企业的明星产品和主打品牌。\n  仓廪实，天下安。近年来，兴化特别注重产业发展与文化传承相结合，将民族文化与稻米文化交融交汇，通过\n建立稻米文化展览馆，展示稻米种植加工的历史和文化，提升粮食市场影响力。2024年9月22日，兴化大米入选国际\n稻米品牌百强榜。绵远流长的文化底蕴、独具风格的稻米文化，在带动农业经济飞速发展的同时，提升了乡村建设\n的审美品位，也增强了居民的认同感和归属感，在浓浓的文化氛围中，有效促进了社会和谐幸福稳定，推动社会治\n理水平不断提升。",["7e3ca2d8bd92160cb8df.pdf",3]]}};
